from typing import List

class Solution:
    def earliestSecondToMarkIndices(self, nums: List[int], changeIndices: List[int]) -> int:
        n = len(nums)
        m = len(changeIndices)
        def check(seconds: int) -> bool:
            needed = [0] * (n + 1)
            for i in range(seconds):
                needed[changeIndices[i]] += 1

            ops = 0
            marked = [False] * (n + 1)
            for i in range(1, n + 1):
                ops += max(0, nums[i-1] - needed[i])

            if ops > seconds - sum(needed[1:]):
                return False

            marked_count = 0
            for i in range(1, n+1):
                if needed[i] > nums[i-1]:
                    continue


            return True


        left, right = 1, m
        ans = -1
        while left <= right:
            mid = (left + right) // 2
            if check(mid):
                ans = mid
                right = mid - 1
            else:
                left = mid + 1
        return ans
